(function(){
  var en = window.AW && window.AW.lang === 'en';
  var BF = [ // [limite superior (nós) inclusive, PT, EN]
    [0, 'Calmaria', 'Calm'], [3, 'Bafagem', 'Light Air'], [6, 'Aragem', 'Light Breeze'], [10, 'Fraco', 'Gentle Breeze'],
    [16, 'Moderado', 'Moderate Breeze'], [21, 'Fresco', 'Fresh Breeze'], [27, 'Muito Fresco', 'Strong Breeze'], [33, 'Forte', 'Near Gale'],
    [40, 'Muito Forte', 'Gale'], [47, 'Duro', 'Severe Gale'], [55, 'Muito Duro', 'Storm'], [63, 'Tempestuoso', 'Violent Storm'], [9999, 'Furacão', 'Hurricane']
  ];
  var DG = [ // [altura PT, altura EN, descrição PT, descrição EN]
    ['0', '0', 'Calmo (sem ondas)', 'Calm (glassy)'], ['0 – 0,1', '0 – 0.1', 'Encrespado', 'Calm (rippled)'], ['0,1 – 0,5', '0.1 – 0.5', 'Suave', 'Smooth'],
    ['0,5 – 1,25', '0.5 – 1.25', 'Fraco', 'Slight'], ['1,25 – 2,5', '1.25 – 2.5', 'Moderado', 'Moderate'], ['2,5 – 4,0', '2.5 – 4.0', 'Grosso', 'Rough'],
    ['4,0 – 6,0', '4.0 – 6.0', 'Muito Grosso', 'Very rough'], ['6,0 – 9,0', '6.0 – 9.0', 'Alto', 'High'], ['9,0 – 14,0', '9.0 – 14.0', 'Muito Alto', 'Very High'],
    ['> 14,0', '> 14.0', 'Fenomenal', 'Phenomenal']
  ];
  var IMG = ["data:image/webp;base64,", "data:image/webp;base64,", "data:image/webp;base64,", "data:image/webp;base64,", "data:image/webp;base64,", "data:image/webp;base64,", "data:image/webp;base64,", "data:image/webp;base64,", "data:image/webp;base64,", "data:image/webp;base64,", "data:image/webp;base64,", "data:image/webp;base64,", "data:image/webp;base64,"];
  var sel = document.getElementById('sopWindIntensity');
  var el = { wind: document.getElementById('seaWind'), h: document.getElementById('seaHeight'), st: document.getElementById('seaState'), img: document.getElementById('seaImg'), cap: document.getElementById('seaCap') };
  if (!sel || !el.wind) return;
  var T = en ? { title: 'Sea conditions', wind: 'Wind (Beaufort)', h: 'Wave height', st: 'Sea state', unit: ' m', warn: 'Storm warning', none: 'No warning', w1: 'Strong Breeze – Near Gale', w2: 'Gale – Severe Gale', w3: 'Storm – Violent Storm', w4: 'Hurricane' }
             : { title: 'Condições do mar', wind: 'Vento (Beaufort)', h: 'Altura das ondas', st: 'Estado do mar', unit: ' m', warn: 'Aviso de tempestade', none: 'Sem aviso', w1: 'Muito Fresco – Forte', w2: 'Muito Forte – Duro', w3: 'Muito Duro – Tempestuoso', w4: 'Furacão' };
  var RED = '#d9534a', MAST = '#222';
  function pennant(y){ return '<polygon points="12,' + y + ' 50,' + (y + 8) + ' 12,' + (y + 16) + '" fill="' + RED + '"/>'; }
  function square(y){ return '<rect x="12" y="' + y + '" width="38" height="30" fill="' + RED + '" stroke="#8a2f28" stroke-width="1"/><rect x="24" y="' + (y + 9) + '" width="14" height="12" fill="#1a1a1a"/>'; }
  function flagSvg(n){
    var body = n === 1 ? pennant(23) : n === 2 ? pennant(14) + pennant(32) : n === 3 ? square(16) : square(1) + square(33);
    return '<svg viewBox="0 0 60 66" xmlns="http://www.w3.org/2000/svg"><rect x="8" y="0" width="2.5" height="66" fill="' + MAST + '" stroke="#888" stroke-width="0.4"/>' + body + '</svg>';
  }
  var dEl = document.getElementById('seaDitch');
  var DITCH = en ? 'AW139 - Ditching approved up to sea state 6' : 'AW139 - Aprovado ditching até mar 6';
  var fEl = document.getElementById('seaFlag'), wEl = document.getElementById('seaWarn');
  document.getElementById('seaLblWarn').textContent = T.warn;
  document.querySelector('.sea-title').textContent = T.title;
  document.getElementById('seaLblWind').textContent = T.wind;
  document.getElementById('seaLblHeight').textContent = T.h;
  document.getElementById('seaLblState').textContent = T.st;
  var last = null;
  function render(){
    var kt = parseInt(sel.value, 10); if (isNaN(kt)) kt = 0;
    if (kt === last) return; last = kt;
    var code = 0; while (code < BF.length - 1 && kt > BF[code][0]) code++;
    var dg = DG[Math.min(code, 9)];   // Beaufort 10–12 não existe na Douglas: usa o nível mais alto (9)
    el.wind.textContent = code + ' · ' + BF[code][en ? 2 : 1];
    el.h.textContent = dg[en ? 1 : 0] + T.unit;
    el.st.textContent = Math.min(code, 9) + ' · ' + dg[en ? 3 : 2];
    var sea = Math.min(code, 9);
    dEl.textContent = DITCH; dEl.classList.toggle('on', sea > 6);
    var wn = code >= 12 ? 4 : code >= 10 ? 3 : code >= 8 ? 2 : code >= 6 ? 1 : 0;
    fEl.innerHTML = wn ? flagSvg(wn) : '';
    wEl.textContent = wn ? T['w' + wn] : T.none;
    el.img.src = IMG[code];
    el.img.alt = BF[code][2];
    el.cap.textContent = BF[code][en ? 2 : 1] + ' — ' + kt + ' kt';
  }
  sel.addEventListener('change', render);
  sel.addEventListener('input', render);
  render();
  var iv = setInterval(function(){ if (!el.wind.isConnected){ clearInterval(iv); return; } render(); }, 250);
})();
